const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:64538/status';
const OUTPUT = path.join(__dirname, 'results', 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  const data = await res.json();

  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, JSON.stringify({ status: data.status }, null, 2) + '\n');

  console.log('status:', data.status);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

